		public AddInfoJobDeclarationLookups AddInfoLookups
		{
			get { return AddInfo.Lookups; }
		}

		public AddInfoJobDeclarationValidation AddInfoValidation
		{
			get { return AddInfo.Validation; }
		}

		AddInfoJobDeclaration AddInfo
		{
			get
			{
				if (fAddInfo == null)
				{
					fAddInfo = new AddInfoJobDeclaration(JE_AddInfoInfo) { EnableConcurrencyResolver = true };
					RegisterEditableChildObject(fAddInfo);
					RegisterListChangedCalledRefreshBinding(fAddInfo);
				}
				return fAddInfo;
			}
		}
		AddInfoJobDeclaration fAddInfo;

